prompt:
Create unit `tasks` and implement `count_digits_iter`: count the decimal digits of n with a loop (0 has one digit). The contract must state that the result is at least 1, at most n + 1, and equals 1 exactly when n < 10.

Required signature (in unit `tasks`):
fn count_digits_iter(n: u64) -> (r: u64)

reference.code:
spec fn digits_ok(n: u64, r: u64) -> bool { 1 <= r && r <= n + 1 && ((n < 10) == (r == 1)) }

#[effects(pure)]
#[uses(digits_ok)]
fn count_digits_iter(n: u64) -> (r: u64)
    ensures digits_ok(n, r),
{
    let mut m: u64 = n;
    let mut c: u64 = 1;
    while m >= 10
        invariant 1 <= c, m <= n, c - 1 <= n - m, c == 1 ==> m == n, c >= 2 ==> n >= 10,
        decreases m,
    {
        m = m / 10;
        c = c + 1;
    }
    c
}

weak_reference.code:
spec fn positive(r: u64) -> bool { r >= 1 }

#[effects(pure)]
#[uses(positive)]
fn count_digits_iter(n: u64) -> (r: u64)
    ensures positive(r),
{
    let mut m: u64 = n;
    let mut c: u64 = 1;
    while m >= 10
        invariant 1 <= c, m <= n, c - 1 <= n - m,
        decreases m,
    {
        m = m / 10;
        c = c + 1;
    }
    c
}
